static long compressTimeBucket(long timeBucket, int dayStep) {
    try {
        int year = (int) (timeBucket / 10000);
        int month = (int) ((timeBucket % 10000) / 100);
        int day = (int) (timeBucket % 100);

        // Calculate the day of the month for the start of the time bucket
        int adjustedDay = ((day - 1) / dayStep) * dayStep + 1;

        // Handle the case where the adjusted day is beyond the last day of the month
        int[] daysInMonth = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        if (year % 4 == 0 && (year % 100 != 0 || year % 400 == 0)) {
            daysInMonth[1] = 29; // Leap year
        }
        if (adjustedDay > daysInMonth[month - 1]) {
            adjustedDay = daysInMonth[month - 1];
        }

        return year * 10000 + month * 100 + adjustedDay;
    } catch (Exception e) {
        // In case of any unexpected error, return the original timeBucket
        return timeBucket;
    }
}

