LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null || session == null || lb == null) {
        throw new IllegalArgumentException("Arguments cannot be null");
    }
    try {
        int length = str.length();
        int utf8Length = 0;
        for (int i = 0; i < length; i++) {
            char c = str.charAt(i);
            if (c < 0x80) {
                utf8Length++;
            } else if (c < 0x800) {
                utf8Length += 2;
            } else if (Character.isSurrogate(c)) {
                if (i + 1 < length && Character.isSurrogatePair(c, str.charAt(i + 1))) {
                    utf8Length += 4;
                    i++;
                } else {
                    throw new IllegalArgumentException("Invalid surrogate pair");
                }
            } else {
                utf8Length += 3;
            }
        }

        lb = ensureCapacity(utf8Length, lb);
        for (int i = 0; i < length; i++) {
            char c = str.charAt(i);
            if (c < 0x80) {
                lb.buffer[lb.offset++] = (byte) c;
            } else if (c < 0x800) {
                lb.buffer[lb.offset++] = (byte) (0xc0 | (c >> 6));
                lb.buffer[lb.offset++] = (byte) (0x80 | (c & 0x3f));
            } else if (Character.isSurrogate(c)) {
                char low = str.charAt(i++);
                int codePoint = Character.toCodePoint(c, low);
                lb.buffer[lb.offset++] = (byte) (0xf0 | (codePoint >> 18));
                lb.buffer[lb.offset++] = (byte) (0x80 | ((codePoint >> 12) & 0x3f));
                lb.buffer[lb.offset++] = (byte) (0x80 | ((codePoint >> 6) & 0x3f));
                lb.buffer[lb.offset++] = (byte) (0x80 | (codePoint & 0x3f));
            } else {
                lb.buffer[lb.offset++] = (byte) (0xe0 | (c >> 12));
                lb.buffer[lb.offset++] = (byte) (0x80 | ((c >> 6) & 0x3f));
                lb.buffer[lb.offset++] = (byte) (0x80 | (c & 0x3f));
            }
        }
        return lb;
    } catch (Exception e) {
        throw new RuntimeException("Error writing UTF-8 string", e);
    }
}

private static LinkedBuffer ensureCapacity(int required, LinkedBuffer lb) {
    if (lb.offset + required > lb.buffer.length) {
        int newSize = Math.max(lb.buffer.length << 1, lb.offset + required);
        byte[] newBuffer = new byte[newSize];
        System.arraycopy(lb.buffer, 0, newBuffer, 0, lb.offset);
        return new LinkedBuffer(newBuffer, lb.next);
    }
    return lb;
}

