private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    if (descriptor.charAt(0) == '(') {
        // It's a method descriptor, extract argument types
        int end = descriptor.indexOf(')');
        if (end == -1) {
            throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
        }
        String argTypes = descriptor.substring(1, end);
        int index = 0;
        while (index < argTypes.length()) {
            char c = argTypes.charAt(index);
            switch (c) {
                case 'B': case 'C': case 'I': case 'S': case 'Z':
                    // These are all single-word types
                    index++;
                    break;
                case 'D': case 'J':
                    // These are double-word types
                    index += 2;
                    break;
                case 'L':
                    // Object type, skip until ';'
                    index = argTypes.indexOf(';', index) + 1;
                    if (index == 0) {
                        throw new IllegalArgumentException("Invalid object type in descriptor");
                    }
                    break;
                case '[':
                    // Array type, skip to the end of the array descriptor
                    do {
                        index++;
                    } while (index < argTypes.length() && argTypes.charAt(index) == '[');
                    if (index == argTypes.length()) {
                        throw new IllegalArgumentException("Invalid array descriptor");
                    }
                    c = argTypes.charAt(index);
                    if (c == 'L') {
                        index = argTypes.indexOf(';', index) + 1;
                        if (index == 0) {
                            throw new IllegalArgumentException("Invalid object type in array descriptor");
                        }
                    } else {
                        index++;
                    }
                    break;
                default:
                    throw new IllegalArgumentException("Invalid character in descriptor: " + c);
            }
        }
    } else {
        // It's a field descriptor, pop based on the type
        switch (descriptor.charAt(0)) {
            case 'B': case 'C': case 'I': case 'S': case 'Z':
                // Single-word types
                break;
            case 'D': case 'J':
                // Double-word types
                break;
            case 'L':
                // Object type
                break;
            case '[':
                // Array type
                break;
            default:
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
        }
    }
}

